let baseUrl = readline();
let N = parseInt(readline());

const params = new URLSearchParams();
for (let i = 0; i < N; i++) {
    let inputs = readline().split(' ');
    params.append(inputs[0], inputs[1]);
}

if (N > 0) {
    baseUrl += `?${params.toString()}`;
}
console.log(baseUrl);
